/* KCMC_VISITOR_WELCOME_20261008: public surfaces only; no photo-within-photo. */
.hero.hero-imagery{background:#f7f1e7;color:#243d50;padding:44px 0 32px;border-bottom:1px solid #daccb4;color-scheme:light}
.hero-imagery .hero-photo{left:auto;right:0;width:58%;filter:none;opacity:1;object-position:center}
.hero-imagery .hero-grid{grid-template-columns:1.2fr 1fr;align-items:end;gap:28px}
.hero-grid>div:first-child{background:#f7f1e7;border-radius:22px;padding:20px}
.hero h1{color:#243d50;font-size:clamp(2.7rem,5.8vw,5.2rem)}
.hero p.lead,.hero .hero-card p{color:#425767}
.hero .eyebrow{color:#77521c}
.hero .hero-card{background:#fffdf9;color:#243d50;border:1px solid #daccb4;margin-top:210px;box-shadow:0 10px 30px rgba(36,61,80,.12)}
.hero .hero-card .pill{background:#e5eef2;color:#243d50}
.hero .action{background:#fffdf9;border:1px solid #c8d2d8;color:#243d50}
.hero .action span{color:#425767}
.hero .btn.secondary{background:#fffdf9;color:#243d50;border:1px solid #526d7f}
.hero .install-callout{background:#e5eef2;color:#243d50;border-color:#b2c6d0}
.hero .install-callout-copy span{color:#425767}
.hero :is(a,button):focus-visible,.invite-neighbor :is(a,button):focus-visible{outline:3px solid #205b79;outline-offset:4px}
.invite-neighbor{background:#f7f1e7;color:#243d50;color-scheme:light}
.invite-neighbor-card{background:#fffdf9;border:1px solid #daccb4;border-radius:24px;padding:clamp(22px,4vw,38px)}
.invite-neighbor h2{font-family:Georgia,serif;font-weight:400;font-size:clamp(1.9rem,3.8vw,3rem);line-height:1.15;margin:.3em 0}
.invite-neighbor p{color:#425767;max-width:70ch}
.invite-neighbor .eyebrow{color:#77521c}
.invite-neighbor .btn.secondary{color:#243d50;background:#fffdf9;border:1px solid #526d7f}
.invite-neighbor .btns,.visit-next-steps .btns{flex-wrap:wrap}
.invite-neighbor button,.visit-next-steps button{white-space:normal;min-height:48px}
.visit-next-steps{border-top:1px solid #647988;margin-top:22px;padding-top:18px}
.visit-next-steps[hidden]{display:none!important}
@media(max-width:900px){.hero.hero-imagery{padding-top:0}.hero-imagery .hero-photo{position:relative;inset:auto;width:100%;height:auto;aspect-ratio:16/10;object-position:center}.hero-imagery:after{display:none}.hero-imagery .hero-grid{grid-template-columns:1fr;gap:20px;margin-top:18px}.hero-grid>div:first-child{padding:12px 0}.hero .hero-card{margin-top:0;max-width:none}.hero h1{font-size:clamp(2.5rem,7.4vw,4.5rem)}}
